function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'Every value in nums must be 0 or 1.';
  if (!Number.isInteger(k) || k < 0 || k > nums.length) return 'k is between 0 and the length of nums.';
  return null;
}

