function longestOnes(nums, k) {
  // Try every starting index and extend the block while the zero budget lasts.
  let best = 0;
  for (let start = 0; start < nums.length; start++) {
    let used = 0;
    for (let end = start; end < nums.length; end++) {
      if (nums[end] === 0) used++;
      if (used > k) break;
      best = Math.max(best, end - start + 1);
    }
  }
  return best;
}

