function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 12);
  // Vary how many zeros there are, from almost none to almost all.
  const zeroRate = [0, 0.1, 0.3, 0.5, 0.8, 1][Math.floor(rand() * 6)];
  const nums = Array.from({ length: n }, () => (rand() < zeroRate ? 0 : 1));
  // k is often small (so the window must slide) but sometimes reaches n.
  const pick = rand();
  const k = pick < 0.15 ? 0 : pick < 0.75 ? Math.floor(rand() * Math.min(n, large ? 60 : 4) + 1) : Math.floor(rand() * (n + 1));
  return [nums, Math.min(k, n)];
}
